// gen:types (foundation-contracts, S0). Generate TypeScript types from the two
// OpenAPI documents using openapi-typescript:
//   packages/contracts/openapi.yaml     -> src/generated/compass-api.ts
//   packages/contracts/events-api.openapi.json -> src/generated/events-api.ts
//
// The generated files live under packages/contracts/src/generated/ and are
// excluded from coverage (vitest config) and from lint type-checking as generated
// code. This script runs openapi-typescript's programmatic API and writes the
// output with a leading banner so the files are clearly machine-generated.
//
// gen:copy must run first so packages/contracts/openapi.yaml exists and is
// byte-identical to the single source.

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import { maybeRunCli } from './cli.mjs';

const thisDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(thisDir, '..', '..');
const contractsDir = resolve(repoRoot, 'packages', 'contracts');

const BANNER =
  '// Generated by openapi-typescript. Do not edit by hand.\n' +
  '// Regenerate with: npm run gen:types\n\n';

export const TARGETS = [
  {
    input: resolve(contractsDir, 'openapi.yaml'),
    output: resolve(contractsDir, 'src', 'generated', 'compass-api.ts'),
  },
  {
    input: resolve(contractsDir, 'events-api.openapi.json'),
    output: resolve(contractsDir, 'src', 'generated', 'events-api.ts'),
  },
];

/**
 * Generate the TypeScript types for every target document.
 *
 * @param {object} [options]
 * @param {Array<{input: string, output: string}>} [options.targets]
 * @returns {Promise<string[]>} the output paths written
 */
export async function genTypes({ targets = TARGETS } = {}) {
  const written = [];
  for (const target of targets) {
    const source = await readFile(target.input, 'utf8');
    const ast = await openapiTS(source);
    const body = astToString(ast);
    await writeFile(target.output, `${BANNER}${body}`, 'utf8');
    written.push(target.output);
  }
  return written;
}

/**
 * Pure CLI driver: returns the exit code and the lines to print without touching
 * the process. Covers the success and error branches in-process.
 *
 * @param {object} [options]
 * @param {Array<{input: string, output: string}>} [options.targets]
 * @returns {Promise<{ code: number, stdout: string, stderr: string }>}
 */
export async function runCli({ targets = TARGETS } = {}) {
  try {
    const written = await genTypes({ targets });
    return { code: 0, stdout: `Generated ${written.length} type files\n`, stderr: '' };
  } catch (error) {
    return { code: 1, stdout: '', stderr: `${error.message}\n` };
  }
}

await maybeRunCli({ runCli, argv1: process.argv[1], metaUrl: import.meta.url });
